-- pixelrp: Builders > Customs > Bsstonino is sorted by what the furni is.
--
-- 122 imported the pack as it came: eleven sub-pages, 'Bsstonino 1' to
-- 'Bsstonino 11', each a mix - floor tiles, a Minion, doughnuts and a violin on
-- one; doors, a camel's head and a crystal ball on another. Now that every
-- piece has a name (216, 217), all 1900 are filed onto 21 pages by type,
-- alphabetical, each wearing one of its own furni as its icon (197's scheme,
-- icon_<7000000 + sprite>.png), none the one Bsstonino itself wears:
--
--   Animals & Figures        60
--   Arabian Palace           24
--   Bathroom & Beauty        62
--   Beds                      9
--   Cushions & Clothing      79
--   Decorations & Art       206
--   Doors                    53
--   Floors & Rugs           120
--   Food & Drink             59
--   Kitchen                  63
--   Lighting                 81
--   Plants & Garden         258
--   Seating                 129
--   Stage & Market           25
--   Storage & Shelves       139
--   Tables & Desks           64
--   Tech & Games             50
--   Walls & Building        225
--   Windows                  84
--   Winter & Christmas       57
--   Wizard & Gothic          53
--
-- Pages have fixed ids (957000+, clear of 122's 945000 block). A furni moves
-- only while it is on one of Bsstonino's own pages; the eleven old pages go
-- once empty. Idempotent: fixed ids, and a second run moves nothing.

SET @builders := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `caption` = 'Builders' LIMIT 1);
SET @customs := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 944000 AND `parent_id` = @builders LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @builders AND `caption` = 'Customs' ORDER BY `id` LIMIT 1));
SET @bsstonino := COALESCE(
    (SELECT `id` FROM `catalog_pages` WHERE `id` = 945000 AND `parent_id` = @customs LIMIT 1),
    (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @customs AND `caption` = 'Bsstonino' ORDER BY `id` LIMIT 1));

INSERT IGNORE INTO `catalog_pages`
    (`id`,`parent_id`,`caption`,`icon_image`,`min_rank`,`min_vip`,`order_num`,`page_link`,
     `page_layout`,`page_strings_1`,`page_strings_2`,`visible`,`enabled`)
