-- No Bsstonino to hang them on: take them back out rather than leave orphans.
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 957000 AND 957099 AND @bsstonino IS NULL;

-- Bsstonino's own pages before the sort: where furni may move from.
DROP TABLE IF EXISTS `_bt_pages`;
CREATE TABLE `_bt_pages` (`id` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
INSERT IGNORE INTO `_bt_pages` (`id`)
    SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @bsstonino AND `id` NOT BETWEEN 957000 AND 957099;

DROP TABLE IF EXISTS `_bt_map`;
CREATE TABLE `_bt_map` (`furni_id` INT NOT NULL PRIMARY KEY, `page_id` INT NOT NULL) ENGINE=InnoDB;
