UPDATE `catalog_items` ci
  JOIN `_bt_pages` s ON s.`id` = ci.`page_id`
  JOIN `_bt_map` m ON CAST(m.`furni_id` AS CHAR) = ci.`item_id`
   SET ci.`page_id` = m.`page_id`;

-- The old pages once empty, then any new page nothing reached.
DELETE p FROM `catalog_pages` p JOIN `_bt_pages` s ON s.`id` = p.`id`
 WHERE NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p
 WHERE p.`id` BETWEEN 957000 AND 957099
   AND NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`);

DROP TABLE `_bt_map`;
DROP TABLE `_bt_pages`;
